            q: 'Угадай мультфильм по голосу. Запись оборвётся перед последним словом фразы. Тут всё меряют чем попало — как вы расстояние до дома: «две остановки и шаурма».',
            a: '«38 попугаев» — Удав: «А в попугаях-то я гораздо ДЛИННЕЕ!»',
            c: 'Удава озвучил Василий Ливанов — он же Карлсон и крокодил Гена; Слонёнка — Михаил Козаков, Мартышку — Надежда Румянцева, Попугая — Всеволод Ларионов. Сценарий — Григорий Остер, режиссёр — Иван Уфимцев; за 15 лет сняли 10 фильмов. Название — по первой серии, где рост Удава мерили слонятами, мартышками и попугаями.',
            hint: 'Герои — удав, слонёнок, мартышка и попугай; в названии есть число.',
