            c: 'За 100 монет дают лишнюю жизнь. Донаты у начинающих стримеров, как и принцесса, вечно «в другом замке». Считается, что кепку Марио нарисовали, чтобы не анимировать волосы при прыжке. Игра разошлась тиражом свыше 40 млн копий и больше 20 лет была самой продаваемой в мире.',
            hint: 'Усатый водопроводчик в красной кепке и грибы, от которых вырастают. Принцесса — как всегда, не в том замке.',
