            a: 'Серебро — «Song #1» (2007). Принимается: Serebro — «Сонг намбер уан» / «Песня №1»',
            c: 'Евровидение-2007, Хельсинки: 3-е место и 207 баллов (победила Сербия, вторая — Верка Сердючка). Группу в 2006-м собрал Максим Фадеев, а песню написал вместе с Даниилом Бабичевым. Ирония судьбы: «Серебро» привезло бронзу. Зато «Песню №1» вы знаете наизусть — английский ведь учили именно по таким хитам.',
            hint: 'Название группы — металл, который дают за второе место; продюсер — Максим Фадеев.',
            img: 'media/img/nash2007/r2_1400_serebro_q.jpg', fx: 'tiles', tiles: 3, aimg: 'media/img/nash2007/r2_1400_serebro_a.jpg',
