            c: 'Войско бунтует, стрельцы уже ломятся в палаты, а Бунша — человек с приоритетами: сначала банкет. Фильм собрал свыше 60 миллионов зрителей и стал лидером проката 1973 года. Если Старый скажет эту фразу сегодня ночью — расходиться запрещено.',
