            a: 'Гол как сокол (принимается: голый как сокол)',
            c: 'Значение — без гроша в кармане. Есть версия, что «сокол» — вовсе не птица, а старинный таран: гладкая болванка без единого сучка. Птицу, выходит, общипали зря. Зато в кошельке теперь так же гладко.',
