            a: 'Бить баклуши',
            c: 'Значение — бездельничать. Баклуши — деревянные чурки, из которых потом точили ложки. Колоть их, как считается, поручали подмастерьям: работа лёгкая, ума не требует. Подмастерья хотя бы оставляли после себя гору заготовок, а «окно №3» — только очередь и «приходите завтра».',
